"use client"

import * as React from "react"
import {
  EmojiPicker as EmojiPickerPrimitive,
  isCustomEmoji,
  type CustomEmoji,
  type CustomSection,
  type EmojiMetadata,
  type HeaderRendererProps,
} from "@ferrucc-io/emoji-picker"

import { cn } from "@/lib/utils"

type EmojiPickerProps = React.ComponentProps<typeof EmojiPickerPrimitive> & {
  placeholder?: string
  containerHeight?: number
  hideStickyHeader?: boolean
}

function EmojiPicker({
  className,
  children,
  placeholder = "Search emoji...",
  containerHeight = 320,
  hideStickyHeader = false,
  ...props
}: EmojiPickerProps) {
  return (
    <EmojiPickerPrimitive
      className={cn(
        "w-[352px] rounded-md border border-border bg-popover text-popover-foreground shadow-md dark:border-border dark:bg-popover focus:ring-ring",
        className
      )}
      {...props}
    >
      {children ?? (
        <>
          <EmojiPickerHeader>
            <EmojiPickerInput placeholder={placeholder} />
          </EmojiPickerHeader>
          <EmojiPickerGroup>
            <EmojiPickerList
              containerHeight={containerHeight}
              hideStickyHeader={hideStickyHeader}
            />
          </EmojiPickerGroup>
          <EmojiPickerPreview>
            {({ previewedEmoji }) => (
              <>
                {previewedEmoji ? (
                  <EmojiPickerContent />
                ) : (
                  <span className="px-1 text-xs text-muted-foreground">
                    Pick an emoji…
                  </span>
                )}
                <EmojiPickerSkinTone />
              </>
            )}
          </EmojiPickerPreview>
        </>
      )}
    </EmojiPickerPrimitive>
  )
}

function EmojiPickerHeader({
  className,
  ...props
}: React.ComponentProps<typeof EmojiPickerPrimitive.Header>) {
  return (
    <EmojiPickerPrimitive.Header
      className={cn("border-b border-border px-2.5 py-2", className)}
      {...props}
    />
  )
}

const EmojiPickerInput = React.forwardRef<
  HTMLInputElement,
  React.ComponentProps<typeof EmojiPickerPrimitive.Input>
>(({ className, ...props }, ref) => {
  return (
    <EmojiPickerPrimitive.Input
      ref={ref}
      className={cn(
        "h-8 bg-muted text-popover-foreground placeholder:text-muted-foreground focus:ring-ring dark:bg-muted dark:text-popover-foreground dark:placeholder:text-muted-foreground",
        className
      )}
      {...props}
    />
  )
})
EmojiPickerInput.displayName = "EmojiPickerInput"

function EmojiPickerGroup({
  className,
  ...props
}: React.ComponentProps<typeof EmojiPickerPrimitive.Group>) {
  return (
    <EmojiPickerPrimitive.Group
      className={cn(
        "[&_[data-slot=emoji-picker-header-label]]:bg-popover/90 [&_[data-slot=emoji-picker-header-label]]:supports-[backdrop-filter]:bg-popover/60 [&_[data-slot=emoji-picker-header-label]_div]:text-muted-foreground [&_[data-slot=emoji-picker-empty]]:text-muted-foreground",
        className
      )}
      {...props}
    />
  )
}

function EmojiPickerList(
  props: React.ComponentProps<typeof EmojiPickerPrimitive.List>
) {
  return <EmojiPickerPrimitive.List {...props} />
}

function EmojiPickerPreview({
  className,
  ...props
}: React.ComponentProps<typeof EmojiPickerPrimitive.Preview>) {
  return (
    <EmojiPickerPrimitive.Preview
      className={cn(
        "border-t border-border bg-muted/40 p-2 text-popover-foreground dark:border-border dark:bg-muted/40",
        className
      )}
      {...props}
    />
  )
}

function EmojiPickerContent(
  props: React.ComponentProps<typeof EmojiPickerPrimitive.Content>
) {
  return <EmojiPickerPrimitive.Content {...props} />
}

function EmojiPickerSkinTone(
  props: React.ComponentProps<typeof EmojiPickerPrimitive.SkinTone>
) {
  return <EmojiPickerPrimitive.SkinTone {...props} />
}

export {
  EmojiPicker,
  EmojiPickerHeader,
  EmojiPickerInput,
  EmojiPickerGroup,
  EmojiPickerList,
  EmojiPickerPreview,
  EmojiPickerContent,
  EmojiPickerSkinTone,
  isCustomEmoji,
}
export type {
  EmojiPickerProps,
  CustomEmoji,
  CustomSection,
  EmojiMetadata,
  HeaderRendererProps,
}
